def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_threat = 0
    urgent_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 6:
                rich_threat += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.35)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    my_urgent = hp <= 3 or no_water_days >= 1
    very_urgent = hp <= 2 or no_water_days >= 2

    if very_urgent:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
        return min(budget, bid)

    if my_urgent:
        base = DAILY_SALARY * (0.78 + 0.12 * scarcity)
        bid = max(base, highest_prev + 1.0 if highest_prev > 0 else base)
        return min(budget, bid)

    if supply >= 22:
        bid = DAILY_SALARY * 0.18
    elif supply >= 19:
        bid = DAILY_SALARY * 0.28
    elif supply >= 17:
        bid = DAILY_SALARY * 0.42
    else:
        bid = DAILY_SALARY * 0.62

    if highest_prev >= DAILY_SALARY * 1.4:
        bid *= 0.75
    elif highest_prev >= DAILY_SALARY * 1.1:
        bid *= 0.85
    elif highest_prev >= DAILY_SALARY * 0.85 and supply <= 17:
        bid = max(bid, DAILY_SALARY * 0.55)
    elif highest_prev > 0 and supply <= 16:
        bid = max(bid, min(highest_prev + 1.5, DAILY_SALARY * 0.9))

    if rich_threat >= 2 and supply >= 19:
        bid *= 0.85
    if urgent_opp >= 1 and supply <= 17:
        bid *= 1.08

    if avg_prev > 0 and avg_prev < DAILY_SALARY * 0.6 and supply <= 16:
        bid = max(bid, avg_prev + 2.0)

    reserve_floor = DAILY_SALARY * 1.2 if hp > 4 else DAILY_SALARY * 0.6
    if budget <= reserve_floor:
        bid = min(bid, DAILY_SALARY * 0.45)

    if bid < 0:
        bid = 0.0
    return min(budget, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Identify alive opponents and use yesterday's bids for immediate pressure estimation.
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # Baseline: conserve budget if not under immediate threat.
    # Escalate if we have no-water streak or low hp.
    if my_hp <= 2.0 or no_water_days >= 2:
        base = DAILY_SALARY * 0.85
    elif my_hp <= 4.0 or no_water_days == 1:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.55

    # Use yesterday's bids from alive opponents to set a competitive target.
    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # If there was strong bidding pressure yesterday, slightly overtake it.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If they were bidding near typical salary, we match/overbid.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If we are healthy, bid a bit less than the leader but still competitive.
            if my_hp > 5.0 and no_water_days == 0:
                target = max(highest_prev_bid * 0.92, DAILY_SALARY * 0.65)
            else:
                target = max(highest_prev_bid * 1.02, DAILY_SALARY * 0.85)
        else:
            # Moderate bids: bid enough to beat the leader by a small margin.
            target = max(highest_prev_bid + 1.5, base)
    else:
        target = base

    # Supply-aware adjustment: when supply is tight, water is more scarce, so bid more.
    # Supply in [15,25] with WATER_REQ=9 means at most 2 units can be fully satisfied.
    scarcity_factor = 0.0
    if supply <= float(WATER_REQ + 6):
        scarcity_factor = 0.15
    elif supply <= float(WATER_REQ + 10):
        scarcity_factor = 0.07
    else:
        scarcity_factor = 0.0

    target = target * (1.0 + scarcity_factor)

    # Near the end of the episode, ensure survival by increasing bids.
    # Episode length is 10 days in meta-round context; use day to approximate.
    if day >= 8:
        target = max(target, DAILY_SALARY * 0.8)

    # Final cap by budget.
    bid = min(my_budget, target)

    # Ensure bid is non-negative.
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {aid: opp for aid, opp in opponents_status.items() if opp['alive']}

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.3)

    # Extract yesterday's bids from opponents' previous_trace
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine base bid based on supply and need
    # If supply is low and we need water, bid higher
    if supply < WATER_REQ * len(alive_opponents) + 1:
        # scarce water
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.9
        elif hp <= 4:
            target = DAILY_SALARY * 0.7
        else:
            target = DAILY_SALARY * 0.5
    else:
        # enough supply
        if hp <= 2 or no_water_days >= 2:
            target = DAILY_SALARY * 0.6
        else:
            target = DAILY_SALARY * 0.3

    # Adjust based on yesterday's bids: if opponents bid high, they may be less aggressive today
    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        max_prev = max(yesterday_bids)
        # If average is high, they might have spent a lot, so we can undercut slightly
        if avg_prev > DAILY_SALARY * 0.6:
            # They spent heavily yesterday; today they might conserve
            adjusted = avg_prev * 0.85
        else:
            # They bid low; they might be desperate today
            adjusted = max_prev + 2.0
        # Blend with our target
        target = (target + adjusted) / 2

    # Ensure we don't exceed budget and stay reasonable
    bid = min(budget, max(target, 1.0))
    return bid
